// Map editor UI: a six-step wizard (source → area → roads → booths → anchors → export).
// Drawing steps run full screen, one task per screen. The venue is drawn in metres (optionally over
// an OSM map or a photo) and exported as a .phop whose map image is generated by the system.
// The free "photo → automatic" flow (create.js) is untouched.
import {
  KINDS, OBSTACLE_KINDS, newVenue, upgradeVenue, makeObstacle, rectObstacle, snap, makeCorridor, addCorridor, makePath, addPath, snapToCorridor, corridorLines, nextId,
  pxPerMeterFor, MAX_PX, buildPayload, checkVenue, makeWall, toggleDoor,
} from './venue.js';
import { findDoors, osmCandidates, photoCandidates, applyCandidates } from './candidates.js';
import { projectPath } from './curves.js';
import { isWalkable, pointInPolygon, obstaclePolygons, nearestOnRing } from './walkable.js';
import { searchPlaces, renderArea, bboxSize, fetchOsmData, projectOsm } from './osm.js';
import { floodRegion, traceOutline } from './trace.js';
import { closing } from './paths.js';
import { drawVenue, renderVenue, drawObstacle } from './mapgen.js';
import { nearestLine } from './geometry.js';
import { buildPhop, saveHandoff } from './phop.js';
import { registerTours, startTour, whenLoaded } from './tour.js';
import { getBlob } from './blobstore.js';
import { buildings, floorsOf, addFloor, setFloorParts, makeRoom, makeInnerWall, inwardAt, ROOM_DOOR_W } from './interior.js';
import { drawIso, isoBounds, isoUnproject } from './iso.js';

const $ = (id) => document.getElementById(id);
const DRAFT_KEY = 'photopath:editor:draft';
const WIZ_KEY = 'photopath:editor:wizard';
const HIT_CSS = 14; // touch tolerance in screen pixels
const TAP_PX = 10; // a pointer that moved less than this is a tap
const MAX_K = 400; // max zoom, screen px per metre
const WIDTHS = [2, 3, 4, 6, 8];
const BG_OPACITY = [0.5, 0.25, 0];

const STEP_TITLE = { 1: '場地從哪來', 2: '設定範圍', 3: '畫路', 7: '畫室內地圖', 4: '放攤位', 5: '放定位點', 6: '檢查與輸出' };
// step ids stay as they were (old drafts keep working); the interior step 7 sits between 3 and 4
const ORDER = [1, 2, 3, 7, 4, 5, 6];
const DRAW_STEPS = [3, 7, 4, 5];
const SURVEY_TARGET = 'photopath:survey:target';
const SURVEY_RESULT = 'photopath:survey:interior';
const MODE_TITLE = { osm: '框範圍', photo: '照片比例', size: '輸入尺寸' };
const open = () => venue.walk === 'open';
const firstTool = (n) => ({ 3: open() ? 'area' : 'corridor', 4: 'block', 5: 'anchor' }[n] || null);
// tools whose taps go to the tool itself, not to picking things on the map
const MODAL = new Set(['door', 'idoor', 'walkdoor', 'wand', 'bgscale']);
const SEL_TIP = '點一下畫好的東西可以移動、刪除或修改。';
const editable = (n) => ({ 3: open() ? ['obstacle', 'path', 'vertex'] : ['corridor', 'path', 'vertex'], 7: inside ? ['part'] : [], 4: ['block'], 5: ['anchor'] }[n] || []);
const stepTitle = (n) => (n === 3 && open() ? '標不能走的地方、畫路' : STEP_TITLE[n]);

const GESTURE = '（一指畫圖・兩指縮放移動；電腦用滾輪縮放、右鍵拖曳）';
const HINTS = {
  corridor: '拖曳畫直路：會自動變成水平或垂直、接上附近的路。路的兩端要碰到別條路才算連通。',
  curve: '沿著道路用手指畫，放開後會整理成平滑的彎路；兩端靠近其他路會自動接上。',
  block: '拖曳畫出攤位或房間，放開後輸入名稱，再在下方選類型。沒有攤位可以直接按下一步。',
  anchor: '點在路上放定位點（例如入口、服務台），至少 2 個，導航時從這些點出發。',
  anchorOpen: '點在能走的地方放定位點（例如入口、服務台），至少 2 個，導航時從這些點出發。',
  curveOpen: '沿著道路用手指畫，放開後會整理成平滑的路。路會畫在地圖上，導航路線會優先走路，但位置不會被限制在路上。',
  area: '圈出不能走的地方：拉一條斜線＝長方形，手指圈一圈＝不規則形狀（水池、草地）。畫完在下方選類型（建築、水池…）。沒標的地方都可以走。',
  door: '點一下建築的牆，在那裡開一個門（約 2 公尺寬）；點已經有的門（綠點）可以移除。建築裡面可以走，只有牆擋路。',
  wand: '在底圖上點一下水池、建築或草地，相連的同色區域會自動標成不能走（類型用下方選單切換）。點錯可以按復原。',
  room: '在建築裡拖曳畫出房間，放開後輸入名稱（例如 101 教室）；門會自動開在朝建築中間那一面。',
  iwall: '拖曳畫一道牆（會自動拉直）。走道、隔間都可以用牆畫出來。',
  idoor: '點一下房間的牆或隔間牆開一個門，點綠點可以移除。1 樓也可以點建築外牆調整出入口。',
  walkdoor: '點一個門（綠點），從那個門走進建築開始走一圈。',
  move: { 3: '拖曳移動路；拖曳彎路上的小圓點可以調整形狀。', 30: '拖曳移動不能走的區域或路；拖曳路上的小圓點可以調整形狀。', 4: '拖曳移動攤位。', 5: '拖曳移動定位點。' },
  erase: { 7: '點一下要刪除的房間或牆。', 3: '點一下要刪除的路。', 30: '點一下要刪除的區域或路。', 4: '點一下要刪除的攤位。', 5: '點一下要刪除的定位點。' },
};
const STEP2_HINT = {
  osm: '搜尋地點，再在地圖上拖曳框出實際的活動範圍（不一定是整個場地）。綠線是 OSM 上的地點邊界。',
  photo: '① 選一張導覽圖照片　② 在照片上點兩個知道實際距離的位置（例如一條走道的兩端）　③ 輸入距離，場地大小就自動算好。',
  size: '輸入場地的實際寬和長（公尺）。',
};

registerTours(
  {
    editor: [
      { el: '#src-choices', title: '一步一件事', text: '先選場地從哪來，接著會一步步帶你：設定範圍 → 畫路 → 放攤位 → 放定位點 → 輸出。' },
    ],
    'editor-draw': [
      { el: '#w-tools', title: '工具在下面', text: '每一步只出現這一步需要的工具。一根手指畫圖；兩根手指捏合縮放、拖曳移動畫面。' },
      { el: '#w-next', title: '完成就按下一步', text: '還有東西沒完成時，按「下一步」會告訴你缺什麼。' },
    ],
  },
  () => (step === 1 ? 'editor' : DRAW_STEPS.includes(step) ? 'editor-draw' : null)
);

let venue = load() || newVenue('我的場地', 30, 20, 'open');
let wiz = loadWiz(); // { step, mode }
let step = 1;
let history = [];
let tool = null;
let corrWidth = 3;
let view = { k: 10, ox: 0, oy: 0 }; // screen = metres * k + offset
let draft = null; // in-progress drag
let bg = null; // { img, x, y, mpp, opacity, osm }
let scalePts = [];
let photoScaled = false;
let hintHidden = false;
let lastStep = wiz.step; // where "繼續編輯" returns to
let inside = null; // step 7: { id, fi } of the building (and floor) being drawn inside
let view3d = false; // step 7: the 3-D view

// ---------- persistence ----------
function load() {
  try {
    const v = JSON.parse(localStorage.getItem(DRAFT_KEY));
    return v && v.version === 1 ? upgradeVenue(v) : null;
  } catch { return null; }
}
function save() {
  try { localStorage.setItem(DRAFT_KEY, JSON.stringify(venue)); } catch { /* storage full / private mode */ }
}
function loadWiz() {
  try {
    const w = JSON.parse(localStorage.getItem(WIZ_KEY));
    if (w && ORDER.includes(w.step)) return { step: w.step, mode: w.mode || null, reviewed: w.reviewed || {} };
  } catch { /* ignore */ }
  return { step: 1, mode: null };
}
function saveWiz() {
  try { localStorage.setItem(WIZ_KEY, JSON.stringify(wiz)); } catch { /* ignore */ }
}

const isEmpty = (v) => !v.corridors.length && !(v.paths || []).length && !v.blocks.length && !v.anchors.length && !(v.obstacles || []).length;

function toast(msg) {
  const t = $('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toast.timer);
  toast.timer = setTimeout(() => t.classList.remove('show'), 2800);
}

/** Replace the venue (undoable). Anchors are re-snapped onto the corridors. */
function commit(next) {
  history.push(JSON.stringify(venue));
  if (history.length > 80) history.shift();
  if (next.walk !== 'open' && (next.corridors.length || (next.paths || []).length)) {
    next = {
      ...next,
      anchors: next.anchors.map((a) => {
        const s = snapToCorridor(next, a);
        return { ...a, x: s.x, y: s.y };
      }),
    };
  }
  venue = next;
  save();
  refresh();
}

function undo() {
  const prev = history.pop();
  if (!prev) return toast('沒有可以復原的步驟');
  venue = JSON.parse(prev);
  sel = null;
  renderSel();
  save();
  refresh();
}

// ---------- canvas & view ----------
const cv = $('ed-map');
const ctx = cv.getContext('2d');
const stage = $('w-stage');

/** Screen pixels per metre. */
const k = () => view.k;
const minK = () => Math.min((stage.clientWidth || 300) / venue.width, (stage.clientHeight || 300) / venue.height) * 0.3;

function layout() {
  const W = stage.clientWidth, H = stage.clientHeight;
  if (!W || !H) return;
  const dpr = window.devicePixelRatio || 1;
  cv.style.width = `${W}px`;
  cv.style.height = `${H}px`;
  cv.width = Math.round(W * dpr);
  cv.height = Math.round(H * dpr);
  draw();
}

/** Show the whole venue. */
function fit() {
  const W = stage.clientWidth, H = stage.clientHeight;
  if (!W || !H) return;
  const pad = 20;
  if (step === 7 && view3d) {
    const b = isoBounds(venue);
    view.k = Math.max(0.01, Math.min((W - 2 * pad) / (b.x1 - b.x0), (H - 2 * pad) / (b.y1 - b.y0)));
    view.ox = (W - (b.x1 - b.x0) * view.k) / 2 - b.x0 * view.k;
    view.oy = (H - (b.y1 - b.y0) * view.k) / 2 - b.y0 * view.k;
    return draw();
  }
  view.k = Math.max(0.01, Math.min((W - 2 * pad) / venue.width, (H - 2 * pad) / venue.height));
  view.ox = (W - venue.width * view.k) / 2;
  view.oy = (H - venue.height * view.k) / 2;
  draw();
}

function zoomAt(sx, sy, k1) {
  k1 = Math.min(MAX_K, Math.max(minK(), k1));
  view.ox = sx - ((sx - view.ox) * k1) / view.k;
  view.oy = sy - ((sy - view.oy) * k1) / view.k;
  view.k = k1;
  draw();
}

function screenXY(e) {
  const r = cv.getBoundingClientRect();
  return { x: e.clientX - r.left, y: e.clientY - r.top };
}
function toM(e) {
  const s = screenXY(e);
  return { x: (s.x - view.ox) / view.k, y: (s.y - view.oy) / view.k };
}

function draw() {
  if (!cv.width || $('full').classList.contains('hidden')) return;
  const dpr = window.devicePixelRatio || 1;
  const s = k();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.fillStyle = '#e2e8f0';
  ctx.fillRect(0, 0, cv.width, cv.height);
  if (step === 7 && view3d) {
    drawIso(ctx, venue, view, dpr, inside?.id);
    $('ed-status').textContent = `立體圖・${buildings(venue).length} 棟建築（點一棟可以畫裡面）`;
    return;
  }
  ctx.setTransform(dpr, 0, 0, dpr, view.ox * dpr, view.oy * dpr);
  ctx.fillStyle = '#f8f6f0';
  ctx.fillRect(0, 0, venue.width * s, venue.height * s);

  if (bg && bg.opacity > 0) {
    ctx.globalAlpha = bg.opacity;
    ctx.drawImage(bg.img, bg.x * s, bg.y * s, bg.img.width * bg.mpp * s, bg.img.height * bg.mpp * s);
    ctx.globalAlpha = 1;
  }

  // grid: the finest readable spacing plus a stronger one (e.g. 1 m + 5 m, or 10 m + 50 m)
  const g = gridSteps();
  for (const [st, color] of [[g.minor, 'rgba(100,116,139,.12)'], [g.major, 'rgba(100,116,139,.3)']]) {
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = 0; x <= venue.width; x += st) { ctx.moveTo(x * s, 0); ctx.lineTo(x * s, venue.height * s); }
    for (let y = 0; y <= venue.height; y += st) { ctx.moveTo(0, y * s); ctx.lineTo(venue.width * s, y * s); }
    ctx.stroke();
  }
  ctx.strokeStyle = '#94a3b8';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(0, 0, venue.width * s, venue.height * s);

  if (step >= 3) {
    if (bg && bg.opacity > 0) ctx.globalAlpha = 0.85;
    drawVenue(ctx, shownVenue(), s, { ground: false, scaleBar: false });
    ctx.globalAlpha = 1;
    if (step === 7) dimOutside(s);

    // corridor centre lines (the equations) on top
    ctx.strokeStyle = '#4f46e5';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (const L of corridorLines(venue, s)) {
      if (L.a === 0) { ctx.moveTo(L.range[0], L.c); ctx.lineTo(L.range[1], L.c); }
      else { ctx.moveTo(L.c, L.range[0]); ctx.lineTo(L.c, L.range[1]); }
    }
    ctx.stroke();
    ctx.lineJoin = 'round';
    for (const [pi, P] of (venue.paths || []).entries()) {
      ctx.beginPath();
      P.points.forEach((q, i) => (i ? ctx.lineTo(q.x * s, q.y * s) : ctx.moveTo(q.x * s, q.y * s)));
      ctx.stroke();
      if (sel?.type === 'path' && sel.i === pi && step === 3) {
        ctx.fillStyle = '#4f46e5';
        for (const q of P.points) { ctx.beginPath(); ctx.arc(q.x * s, q.y * s, 5, 0, Math.PI * 2); ctx.fill(); }
      }
    }
    ctx.globalAlpha = step === 5 ? 1 : 0.45;
    // many anchors (e.g. spread out automatically): small dots, so the map stays readable
    const dense = venue.anchors.length > 40;
    venue.anchors.forEach((a, i) => (dense ? dot(a.x * s, a.y * s) : pin(a.x * s, a.y * s, i + 1)));
    ctx.globalAlpha = 1;
  }

  if (review && review.step === step) drawReview(s);
  if (sel) drawSel(s);

  if (draft?.kind === 'curve' && draft.pts.length > 1) {
    ctx.strokeStyle = 'rgba(79,70,229,.5)';
    ctx.lineWidth = Math.max(4, corrWidth * s);
    ctx.lineCap = 'round';
    ctx.beginPath();
    draft.pts.forEach((q, i) => (i ? ctx.lineTo(q.x * s, q.y * s) : ctx.moveTo(q.x * s, q.y * s)));
    ctx.stroke();
  }
  if (draft?.kind === 'corridor' && draft.c) {
    const c = draft.c;
    ctx.strokeStyle = 'rgba(79,70,229,.5)';
    ctx.lineWidth = Math.max(4, c.width * s);
    ctx.lineCap = 'butt';
    ctx.beginPath();
    if (c.axis === 'h') { ctx.moveTo(c.from * s, c.c * s); ctx.lineTo(c.to * s, c.c * s); }
    else { ctx.moveTo(c.c * s, c.from * s); ctx.lineTo(c.c * s, c.to * s); }
    ctx.stroke();
  }
  if (draft?.kind === 'area' && draft.pts.length > 1 && straightish(draft.pts)) {
    const b = rectOf(draft.p0, draft.p1);
    ctx.fillStyle = 'rgba(220,38,38,.12)';
    ctx.fillRect(b.x * s, b.y * s, b.w * s, b.h * s);
    ctx.setLineDash([6, 4]);
    ctx.strokeStyle = '#dc2626';
    ctx.lineWidth = 2;
    ctx.strokeRect(b.x * s, b.y * s, b.w * s, b.h * s);
    ctx.setLineDash([]);
  } else if (draft?.kind === 'area' && draft.pts.length > 1) {
    ctx.fillStyle = 'rgba(220,38,38,.18)';
    ctx.strokeStyle = '#dc2626';
    ctx.lineWidth = 2;
    ctx.beginPath();
    draft.pts.forEach((q, i) => (i ? ctx.lineTo(q.x * s, q.y * s) : ctx.moveTo(q.x * s, q.y * s)));
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  }
  if (draft?.kind === 'iwall' && draft.p1) {
    const w = makeInnerWall(curBuilding(), [], draft.p0, draft.p1);
    if (w) {
      ctx.strokeStyle = '#6366f1';
      ctx.lineWidth = Math.max(3, s * 0.3);
      ctx.beginPath();
      ctx.moveTo(w.points[0].x * s, w.points[0].y * s);
      ctx.lineTo(w.points[1].x * s, w.points[1].y * s);
      ctx.stroke();
    }
  }
  if (draft?.kind === 'block' || draft?.kind === 'room') {
    const b = rectOf(draft.p0, draft.p1);
    ctx.setLineDash([6, 4]);
    ctx.strokeStyle = '#d97706';
    ctx.lineWidth = 2;
    ctx.strokeRect(b.x * s, b.y * s, b.w * s, b.h * s);
    ctx.setLineDash([]);
  }
  if (scalePts.length) {
    ctx.strokeStyle = '#e11d48';
    ctx.lineWidth = 2;
    ctx.beginPath();
    scalePts.forEach((p, i) => (i ? ctx.lineTo(p.x * s, p.y * s) : ctx.moveTo(p.x * s, p.y * s)));
    ctx.stroke();
    ctx.fillStyle = '#e11d48';
    for (const p of scalePts) { ctx.beginPath(); ctx.arc(p.x * s, p.y * s, 7, 0, Math.PI * 2); ctx.fill(); }
  }

  $('ed-status').textContent = `${venue.width} × ${venue.height} m・格線 ${g.minor} m`;
}

const GRID = [1, 5, 10, 50, 100, 500];
function gridSteps() {
  const i = Math.max(0, GRID.findIndex((st) => st * k() >= 8));
  return { minor: GRID[i], major: GRID[Math.min(i + 1, GRID.length - 1)] };
}

function pin(x, y, n) {
  ctx.fillStyle = '#ea580c';
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(x, y, 12, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = '#fff';
  ctx.font = '700 12px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(String(n), x, y + 0.5);
}

function dot(x, y) {
  ctx.fillStyle = '#ea580c';
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(x, y, 4.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
}

const rectOf = (p0, p1) => {
  const x0 = snap(Math.min(p0.x, p1.x)), x1 = snap(Math.max(p0.x, p1.x));
  const y0 = snap(Math.min(p0.y, p1.y)), y1 = snap(Math.max(p0.y, p1.y));
  return { x: x0, y: y0, w: x1 - x0, h: y1 - y0 };
};

// ---------- hit testing (only what the current step edits) ----------
function hit(p) {
  const allow = new Set(editable(step));
  const tol = HIT_CSS / k();
  if (allow.has('part')) {
    const parts = curParts();
    let best = -1, bd = Infinity;
    parts.forEach((q, i) => {
      if (q.points.length === 2) {
        const n = nearestOnRing(q.points, p);
        if (n.dist < tol && n.dist < bd) { bd = n.dist; best = i; }
      }
    });
    if (best >= 0) return { type: 'part', i: best };
    parts.forEach((q, i) => {
      if (q.points.length < 3 || !pointInPolygon(p, q.points)) return;
      const xs = q.points.map((r) => r.x), ys = q.points.map((r) => r.y);
      const a = (Math.max(...xs) - Math.min(...xs)) * (Math.max(...ys) - Math.min(...ys));
      if (a < bd) { bd = a; best = i; }
    });
    return best >= 0 ? { type: 'part', i: best } : null;
  }
  if (allow.has('anchor')) {
    const i = venue.anchors.findIndex((a) => Math.hypot(a.x - p.x, a.y - p.y) < tol * 1.3);
    return i >= 0 ? { type: 'anchor', i } : null;
  }
  if (allow.has('vertex') && sel?.type === 'path' && venue.paths?.[sel.i]) {
    const j = venue.paths[sel.i].points.findIndex((q) => Math.hypot(q.x - p.x, q.y - p.y) < tol);
    if (j >= 0) return { type: 'vertex', i: sel.i, j };
  }
  if (allow.has('corridor') || allow.has('path')) {
    const way = wayAt(p);
    if (way && way.dist < Math.max(tol, way.width / 2)) return way.hit;
    if (allow.has('corridor')) return null; // open venues: fall through to the areas
  }
  if (allow.has('obstacle')) {
    let best = -1, area = Infinity; // smallest obstacle containing p
    (venue.obstacles || []).forEach((o, i) => {
      if (!pointInPolygon(p, o.points)) return;
      const xs = o.points.map((q) => q.x), ys = o.points.map((q) => q.y);
      const a = (Math.max(...xs) - Math.min(...xs)) * (Math.max(...ys) - Math.min(...ys));
      if (a < area) { area = a; best = i; }
    });
    return best >= 0 ? { type: 'obstacle', i: best } : null;
  }
  if (allow.has('block')) {
    let bi = -1; // smallest block containing p
    venue.blocks.forEach((b, i) => {
      if (p.x >= b.x && p.x <= b.x + b.w && p.y >= b.y && p.y <= b.y + b.h) {
        if (bi < 0 || b.w * b.h < venue.blocks[bi].w * venue.blocks[bi].h) bi = i;
      }
    });
    return bi >= 0 ? { type: 'block', i: bi } : null;
  }
  return null;
}

/** Nearest straight corridor or curve to p (metres). */
function wayAt(p) {
  let best = null;
  const lines = corridorLines(venue);
  if (lines.length) {
    const n = nearestLine(lines, p);
    const i = venue.corridors.findIndex((x) => x.id === n.line.id);
    best = { dist: n.dist, width: venue.corridors[i].width || 3, hit: { type: 'corridor', i } };
  }
  (venue.paths || []).forEach((P, i) => {
    const q = projectPath(P, p);
    if (!best || q.dist < best.dist) best = { dist: q.dist, width: P.width || 3, hit: { type: 'path', i } };
  });
  return best;
}

// ---------- tools ----------
function setTool(t) {
  tool = t;
  draft = null;
  scalePts = [];
  sel = null;
  $('more-menu').classList.add('hidden');
  renderSel();
  document.querySelectorAll('.tool').forEach((b) => b.classList.toggle('active', b.dataset.tool === t));
  setHint();
  draw();
}

function setHint() {
  let text;
  if (step === 2) text = STEP2_HINT[wiz.mode] || '';
  else if (step === 7 && !inside) text = '點一棟建築，畫它裡面的房間和走道（可以手動畫，也可以拿手機走一圈自動畫）。每棟可以有好幾層，按「立體圖」看整體。';
  else {
    const h = open() && HINTS[`${tool}Open`] ? HINTS[`${tool}Open`] : HINTS[tool];
    text = (typeof h === 'object' ? h[step === 3 && open() ? 30 : step] : h || '') + (MODAL.has(tool) ? '' : SEL_TIP) + GESTURE;
  }
  $('w-hint-text').textContent = text;
  $('w-hint').classList.toggle('hidden', hintHidden);
  $('w-hint-show').classList.toggle('hidden', !hintHidden);
}
$('w-hint-x').addEventListener('click', () => { hintHidden = true; setHint(); requestAnimationFrame(layout); });
$('w-hint-show').addEventListener('click', () => { hintHidden = false; setHint(); requestAnimationFrame(layout); });

// pointers: one finger = the current tool, two fingers = pinch zoom + pan
const pts = new Map();
let gesture = null; // { kind: 'pinch', ... } | { kind: 'pan', last }
let tap = null; // { s: screen point, p: metres, moved }

const dist2 = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
const mid = (a, b) => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });

function pinchStart() {
  const [a, b] = [...pts.values()];
  return { kind: 'pinch', d0: dist2(a, b) || 1, c0: mid(a, b), k0: view.k, ox0: view.ox, oy0: view.oy };
}

cv.addEventListener('contextmenu', (e) => e.preventDefault());
cv.addEventListener('pointerdown', (e) => {
  try { cv.setPointerCapture(e.pointerId); } catch { /* synthetic pointer */ }
  pts.set(e.pointerId, screenXY(e));
  if (e.pointerType === 'mouse' && e.button !== 0) {
    cancelDraft();
    gesture = { kind: 'pan', last: screenXY(e) };
    return;
  }
  if (pts.size >= 2) {
    cancelDraft();
    tap = null;
    gesture = pinchStart();
    return;
  }
  if (!gesture && step === 7 && view3d) { gesture = { kind: 'pan', last: screenXY(e) }; tap = { s: screenXY(e), moved: false }; return; }
  if (!gesture) down(e);
});
cv.addEventListener('pointermove', (e) => {
  if (!pts.has(e.pointerId)) return;
  pts.set(e.pointerId, screenXY(e));
  if (gesture?.kind === 'pinch' && pts.size >= 2) {
    const [a, b] = [...pts.values()];
    const g = gesture;
    const k1 = Math.min(MAX_K, Math.max(minK(), (g.k0 * dist2(a, b)) / g.d0));
    const c = mid(a, b);
    const mx = (g.c0.x - g.ox0) / g.k0, my = (g.c0.y - g.oy0) / g.k0;
    view.k = k1;
    view.ox = c.x - mx * k1;
    view.oy = c.y - my * k1;
    draw();
  } else if (gesture?.kind === 'pan') {
    const s = screenXY(e);
    view.ox += s.x - gesture.last.x;
    view.oy += s.y - gesture.last.y;
    gesture.last = s;
    draw();
  } else if (!gesture) move(e);
});
function pointerEnd(e) {
  if (!pts.has(e.pointerId)) return;
  pts.delete(e.pointerId);
  if (gesture) {
    if (!pts.size) gesture = null; // wait until every finger is up
    if (step === 7 && view3d && tap && !pts.size) {
      const t = tap;
      tap = null;
      if (dist2(screenXY(e), t.s) <= TAP_PX) pickBuilding(isoUnproject({ x: (t.s.x - view.ox) / view.k, y: (t.s.y - view.oy) / view.k }));
    }
    return;
  }
  if (e.type === 'pointercancel') { cancelDraft(); tap = null; return; }
  up();
}
cv.addEventListener('pointerup', pointerEnd);
cv.addEventListener('pointercancel', pointerEnd);
cv.addEventListener('wheel', (e) => {
  e.preventDefault();
  const s = screenXY(e);
  zoomAt(s.x, s.y, view.k * Math.exp(-e.deltaY * 0.0015));
}, { passive: false });

function down(e) {
  const p = toM(e);
  tap = { s: screenXY(e), p, moved: false };
  if (sel && !MODAL.has(tool)) {
    const h = hit(p);
    if (h && (h.type === 'vertex' ? sel.type === 'path' && h.i === sel.i : h.type === sel.type && h.i === sel.i)) {
      draft = { kind: 'move', h, p0: p, orig: JSON.parse(JSON.stringify(venue)), moved: false };
      return;
    }
  }
  if (tool === 'corridor' || tool === 'block' || tool === 'room' || tool === 'iwall') draft = { kind: tool, p0: p, p1: p, c: null };
  else if (tool === 'curve' || tool === 'area') draft = { kind: tool, pts: [p], p0: p, p1: p };
}

function move(e) {
  if (tap && dist2(screenXY(e), tap.s) > TAP_PX) tap.moved = true;
  if (!draft) return;
  const p = toM(e);
  draft.p1 = p;
  if (draft.kind === 'curve' || draft.kind === 'area') {
    const last = draft.pts[draft.pts.length - 1];
    if (Math.hypot(p.x - last.x, p.y - last.y) >= 0.15) draft.pts.push(p);
  } else if (draft.kind === 'corridor') draft.c = makeCorridor(venue, draft.p0, p, corrWidth);
  else if (draft.kind === 'move') {
    const dx = snap(p.x - draft.p0.x), dy = snap(p.y - draft.p0.y);
    venue = moved(draft.orig, draft.h, dx, dy);
    draft.moved = dx !== 0 || dy !== 0;
  }
  draw();
}

function up() {
  const t = tap;
  let d = draft;
  tap = null;
  draft = null;
  const isTap = t && !t.moved;
  if (d && d.kind !== 'move' && isTap) d = null; // a tap with a drawing tool picks instead of drawing
  if (d) {
    if (d.kind === 'corridor') {
      if (d.c) commit(addCorridor(venue, d.c));
      else draw();
    } else if (d.kind === 'curve') {
      const P = makePath(venue, d.pts, corrWidth);
      if (P) commit(addPath(venue, P));
      else draw();
    } else if (d.kind === 'block') addBlock(rectOf(d.p0, d.p1 || d.p0));
    else if (d.kind === 'room') addRoom(rectOf(d.p0, d.p1 || d.p0));
    else if (d.kind === 'iwall') {
      const w = makeInnerWall(curBuilding(), curParts(), { x: snap(d.p0.x), y: snap(d.p0.y) }, { x: snap(d.p1.x), y: snap(d.p1.y) });
      if (w) commit(setFloorParts(venue, inside.id, inside.fi, [...curParts(), w]));
      else { toast('牆至少要 1 公尺長'); draw(); }
    }
    else if (d.kind === 'area') {
      // a straight-ish stroke is a rectangle corner to corner; anything else is the outline itself
      const r = rectOf(d.p0, d.p1 || d.p0);
      const o = newObstacle(straightish(d.pts) ? [{ x: r.x, y: r.y }, { x: r.x + r.w, y: r.y }, { x: r.x + r.w, y: r.y + r.h }, { x: r.x, y: r.y + r.h }] : d.pts, $('obs-kind').value);
      if (o) {
        commit({ ...venue, obstacles: [...venue.obstacles, o] });
        select({ type: 'obstacle', i: venue.obstacles.length - 1 });
        toast(o.shape === 'wall' ? WALL_TIP : '畫好了，在下方選它是什麼（草地、水池、建築…）');
      } else { toast('範圍太小，請畫大一點'); draw(); }
    }
    else if (d.kind === 'move') {
      if (!d.moved) { venue = d.orig; return draw(); }
      const next = venue;
      venue = d.orig;
      commit(next);
    }
    return;
  }
  if (!isTap) return;
  if (MODAL.has(tool)) {
    if (tool === 'bgscale') bgScalePoint(t.p);
    else if (tool === 'wand') wandAt(t.p);
    else if (tool === 'door') doorAt(t.p);
    else if (tool === 'idoor') innerDoorAt(t.p);
    else if (tool === 'walkdoor') walkFrom(t.p);
    return;
  }
  if (step === 7 && !inside) return pickBuilding(t.p);
  const h = hit(t.p);
  if (h) return select(h.type === 'vertex' ? { type: 'path', i: h.i } : h);
  if (sel) return select(null);
  if (tool === 'anchor') addAnchor(t.p);
  else if (tool === 'bgscale') bgScalePoint(t.p);
}

const WALL_TIP = '建築只有牆會擋路，裡面可以走。門先放在最長那面牆的中間，要改就按下方的「開門」';

/** Obstacle from an outline; a building becomes walls with one door (people can walk inside). */
function newObstacle(raw, kind) {
  const o = makeObstacle(venue, raw, kind);
  if (!o || kind !== 'building') return o;
  const others = obstaclePolygons(venue).filter((x) => x.kind !== 'grass').map((x) => x.points);
  return makeWall(venue, o.points, '', findDoors(o.points, [], [], { others, width: venue.width, height: venue.height }).doors);
}

/** Door tool: open a door in the nearest building wall, or close the door that was tapped. */
function doorAt(p) {
  const tol = Math.max(HIT_CSS / k(), 1);
  let best = null;
  (venue.obstacles || []).forEach((o, i) => {
    if (o.shape !== 'wall') return;
    const n = nearestOnRing(o.points, p);
    if (n.dist <= tol && (!best || n.dist < best.d)) best = { i, d: n.dist };
  });
  if (!best) return toast('請點在建築的牆上（類型選「建築」標出來的才有牆）');
  const o = venue.obstacles[best.i];
  const next = toggleDoor(o, p);
  commit({ ...venue, obstacles: venue.obstacles.map((x, j) => (j === best.i ? next : x)) });
  toast(next.doors.length < (o.doors || []).length ? '已移除這個門' : '已在牆上開一個門；點綠點可以移除');
}

function cancelDraft() {
  if (draft?.kind === 'move') venue = draft.orig;
  draft = null;
  draw();
}

function moved(v, h, dx, dy) {
  const n = JSON.parse(JSON.stringify(v));
  if (h.type === 'anchor') { n.anchors[h.i].x += dx; n.anchors[h.i].y += dy; }
  else if (h.type === 'block') { n.blocks[h.i].x += dx; n.blocks[h.i].y += dy; }
  else if (h.type === 'vertex') { n.paths[h.i].points[h.j].x += dx; n.paths[h.i].points[h.j].y += dy; }
  else if (h.type === 'path') for (const q of n.paths[h.i].points) { q.x += dx; q.y += dy; }
  else if (h.type === 'obstacle') for (const q of [...n.obstacles[h.i].points, ...(n.obstacles[h.i].doors || [])]) { q.x += dx; q.y += dy; }
  else {
    const c = n.corridors[h.i];
    if (c.axis === 'h') { c.c += dy; c.from += dx; c.to += dx; } else { c.c += dx; c.from += dy; c.to += dy; }
  }
  return n;
}

function addBlock(r) {
  if (r.w < 0.5 || r.h < 0.5) return draw();
  const kind = $('block-kind').value;
  const id = nextId(venue.blocks, 'B');
  draw();
  const name = prompt(`${KINDS[kind].label}名稱`, `${KINDS[kind].label} ${id.slice(1)}`);
  if (name === null) return draw();
  commit({ ...venue, blocks: [...venue.blocks, { id, name: name.trim() || KINDS[kind].label, kind, ...r }] });
  select({ type: 'block', i: venue.blocks.length - 1 });
}

function addAnchor(p) {
  let s;
  if (open()) {
    if (!isWalkable(venue, p)) {
      const o = obstaclePolygons(venue).find((x) => pointInPolygon(p, x.points));
      const what = o ? (o.name || OBSTACLE_KINDS[o.kind]?.label || KINDS[o.kind]?.label || '') : '';
      return toast(`這裡不能走${what ? `（${what}）` : ''}，請放在可以走的地方`);
    }
    s = { x: Math.round(p.x * 10) / 10, y: Math.round(p.y * 10) / 10 };
  } else {
    s = snapToCorridor(venue, p);
    if (!s) return toast('請先回上一步畫路，定位點必須在路上');
  }
  const name = prompt('定位點名稱（例如：東側入口、服務台）', '');
  if (!name || !name.trim()) return;
  const landmark = (prompt('現場看起來是什麼？（選填，例如：噴水池、藍色帳篷）\n之後校正位置時，會請你把手機對準它。', '') || '').trim();
  const a = { id: nextId(venue.anchors, 'A'), name: name.trim(), x: s.x, y: s.y };
  if (landmark) a.landmark = landmark;
  commit({ ...venue, anchors: [...venue.anchors, a] });
}

function erase(p) {
  removeHit(hit(p));
}
function removeHit(h) {
  if (!h) return;
  sel = null;
  renderSel();
  if (h.type === 'part') return commit(setFloorParts(venue, inside.id, inside.fi, curParts().filter((_, i) => i !== h.i)));
  const key = { anchor: 'anchors', block: 'blocks', corridor: 'corridors', path: 'paths', obstacle: 'obstacles' }[h.type];
  commit({ ...venue, [key]: venue[key].filter((_, i) => i !== h.i) });
}

// ---------- photo background (step 2, photo mode) ----------
function bgScalePoint(p) {
  if (!bg) return toast('請先按下方「選照片」');
  scalePts.push(p);
  draw();
  if (scalePts.length < 2) return toast('再點第二個位置');
  setTimeout(() => {
    const [a, b] = scalePts;
    scalePts = [];
    const cur = Math.hypot(b.x - a.x, b.y - a.y);
    const real = parseFloat(prompt('這兩點之間的實際距離是幾公尺？', ''));
    if (!(real > 0) || cur <= 0) return draw();
    const mpp = (bg.mpp * real) / cur;
    const W = Math.round(bg.img.width * mpp), H = Math.round(bg.img.height * mpp);
    if (W < 5 || H < 5 || W > 1000 || H > 1000) {
      toast(`照片換算成 ${W} × ${H} m，超出 5–1000 m，請重新點兩點`);
      return draw();
    }
    Object.assign(bg, { mpp, x: 0, y: 0 });
    photoScaled = true;
    const { geo, ...rest } = venue;
    commit({ ...rest, width: W, height: H });
    fit();
    toast(`場地大小：${W} × ${H} m。可以按「下一步」開始畫路`);
  }, 30);
}

$('bg-file').addEventListener('change', async (e) => {
  const f = e.target.files[0];
  e.target.value = '';
  if (!f) return;
  try {
    const img = await createImageBitmap(f);
    setBackground(img, false);
    startPhotoRecognition(img);
    photoScaled = false;
    const H = Math.max(5, Math.min(1000, Math.round(img.height * bg.mpp)));
    if (H !== venue.height) commit({ ...venue, height: H });
    fit();
    toast('在照片上點兩個知道實際距離的位置（同時在背景辨識照片內容）');
  } catch { toast('無法讀取這張圖片'); }
});

/** Show img under the grid, scaled to the venue width (osmMap: an OSM map, shown with attribution). */
function setBackground(img, osmMap) {
  bg = { img, x: 0, y: 0, mpp: venue.width / img.width, opacity: osmMap ? 0.5 : 0.6, osm: osmMap };
  updateBgButton();
  draw();
}

function updateBgButton() {
  const show = !!bg && DRAW_STEPS.includes(step) && !(step === 7 && view3d);
  $('tool-wand').classList.toggle('hidden', !(bg && step === 3 && open()));
  $('btn-bg').classList.toggle('hidden', !show);
  $('bg-attr').classList.toggle('hidden', !(bg?.osm && bg.opacity > 0));
  if (bg) $('bg-label').textContent = bg.opacity ? `底圖 ${Math.round(bg.opacity * 100)}%` : '底圖 關';
}
$('btn-bg').addEventListener('click', () => {
  if (!bg) return;
  const i = BG_OPACITY.indexOf(bg.opacity);
  bg.opacity = BG_OPACITY[(i + 1) % BG_OPACITY.length];
  updateBgButton();
  draw();
});

/** The OSM background is not stored in the draft; fetch it again from the saved bbox. */
async function restoreOsmBackground() {
  const geo = venue.geo;
  try {
    const area = await renderArea(geo.bbox, 2048);
    if (venue.geo === geo && !bg) setBackground(area.canvas, true);
  } catch { /* offline: draw without the map */ }
}

// ---------- wizard ----------
function go(n) {
  step = n;
  wiz.step = n;
  if (n >= 3) lastStep = n;
  saveWiz();
  const fullscreen = n !== 1 && n !== 6;
  if (n !== 7) { inside = null; view3d = false; }
  $('s1').classList.toggle('hidden', n !== 1);
  $('s6').classList.toggle('hidden', n !== 6);
  $('full').classList.toggle('hidden', !fullscreen);
  document.body.classList.toggle('wiz-lock', fullscreen);
  pts.clear();
  gesture = null;
  if (fullscreen) enterFull();
  window.scrollTo(0, 0);
  refresh();
  if (n === 1) whenLoaded(() => startTour('editor'), 300);
}

function enterFull() {
  $('w-step').textContent = `${ORDER.indexOf(step) + 1}／${ORDER.length}`;
  $('w-prev').textContent = '← 上一步';
  $('w-title').textContent = step === 2 ? `${STEP_TITLE[2]}：${MODE_TITLE[wiz.mode] || ''}` : stepTitle(step);
  $('walk-seg').classList.toggle('hidden', step !== 3);
  document.querySelectorAll('#walk-seg button').forEach((b) => b.classList.toggle('on', b.dataset.walk === (venue.walk || 'roads')));
  $('w-next').textContent = step === 5 ? '完成 →' : '下一步 →';
  const osmPane = step === 2 && wiz.mode === 'osm';
  const sizePane = step === 2 && wiz.mode === 'size';
  $('pane-osm').classList.toggle('hidden', !osmPane);
  $('pane-size').classList.toggle('hidden', !sizePane);
  showTools();
  $('w-tools').classList.toggle('hidden', step === 2 && wiz.mode === 'size');
  review = null;
  $('auto-sheet').classList.add('hidden');
  updateBgButton();
  $('btn-fit').classList.toggle('hidden', osmPane || sizePane);
  sel = null;
  if (step === 2 && wiz.mode === 'photo') setTool('bgscale');
  else setTool(step === 7 && inside ? 'room' : firstTool(step));
  if (step === 7) updateInside();
  if (sizePane) {
    $('v-width').value = venue.width;
    $('v-height').value = venue.height;
  }
  if (osmPane) osmEnter();
  if (step >= 3 && venue.geo && (!bg || !bg.osm)) { bg = null; restoreOsmBackground(); }
  layout();
  if (step === 7 && inside) fitBuilding(); else fit();
  if (step === 3) whenLoaded(() => startTour('editor-draw'), 400);
  maybeOfferReview();
}

// ---------- the picked thing: what you can do with it (move by dragging it, type, name, doors, delete) ----------
let sel = null; // a hit: { type: obstacle | path | corridor | block | anchor | part, i }
let doorBack = null; // tool to return to after the door mode

/** A stroke that is nearly a straight line (drawn corner to corner = a rectangle). */
function straightish(pts) {
  if (pts.length < 2) return true;
  let L = 0;
  for (let i = 1; i < pts.length; i++) L += Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y);
  const a = pts[0], z = pts[pts.length - 1];
  return L <= 1.25 * Math.hypot(z.x - a.x, z.y - a.y) + 0.5;
}

function select(h) {
  sel = h;
  renderSel();
  draw();
}

/** The picked thing itself. */
function selItem(h = sel) {
  if (!h) return null;
  if (h.type === 'part') return curParts()[h.i] || null;
  const key = { anchor: 'anchors', block: 'blocks', corridor: 'corridors', path: 'paths', obstacle: 'obstacles' }[h.type];
  return venue[key]?.[h.i] || null;
}

function replaceSel(next) {
  if (sel.type === 'part') return commit(setFloorParts(venue, inside.id, inside.fi, curParts().map((x, i) => (i === sel.i ? next : x))));
  const key = { anchor: 'anchors', block: 'blocks', corridor: 'corridors', path: 'paths', obstacle: 'obstacles' }[sel.type];
  commit({ ...venue, [key]: venue[key].map((x, i) => (i === sel.i ? next : x)) });
}

/** Change what an area is; becoming a building turns it into walls with a door, and back. */
function obstacleKind(o, kind) {
  if (kind === 'building' && o.shape !== 'wall') {
    const w = newObstacle(o.points, 'building');
    return w ? { ...w, id: o.id, name: o.name } : { ...o, kind };
  }
  if (kind !== 'building' && o.shape === 'wall') {
    const { shape, doors, floors, ...rest } = o;
    return { ...rest, kind };
  }
  return { ...o, kind };
}

const mk = (tag, props = {}, ...kids) => { const el = Object.assign(document.createElement(tag), props); el.append(...kids); return el; };
const btn = (text, onclick, cls = 'btn sm') => mk('button', { className: cls, textContent: text, onclick });

function renderSel() {
  const bar = $('sel-bar');
  if (!bar) return;
  const kids = [];
  if (tool === 'door' || tool === 'idoor') {
    kids.push(mk('span', { className: 'sel-name', textContent: '🚪 點牆開一個門，點綠點移除' }));
    kids.push(btn('✓ 完成', () => setTool(doorBack || firstTool(step)), 'btn primary sm'));
  } else if (tool === 'walkdoor') {
    kids.push(mk('span', { className: 'sel-name', textContent: '🚶 點你要從哪個門（綠點）走進去' }));
    kids.push(btn('取消', () => setTool('room')));
  } else if (sel && selItem()) {
    const it = selItem();
    const t = sel.type;
    const label = {
      obstacle: () => it.name || (it.shape === 'wall' ? '建築' : OBSTACLE_KINDS[it.kind]?.label || '不能走的地方'),
      path: () => '路', corridor: () => '路', block: () => it.name, anchor: () => it.name,
      part: () => (it.points.length === 2 ? '牆' : it.name || '房間'),
    }[t]();
    kids.push(mk('span', { className: 'sel-name', textContent: label }, mk('small', { textContent: '拖曳它可以移動' })));
    if (t === 'obstacle') {
      const s = mk('select', { title: '類型' });
      for (const [key, v] of Object.entries(OBSTACLE_KINDS)) s.append(new Option(v.label, key, false, key === it.kind));
      s.onchange = () => {
        if (it.floors?.some((f) => f.parts?.length) && !confirm('改成別的類型會刪掉這棟建築裡面畫好的房間，要繼續嗎？')) { s.value = it.kind; return; }
        $('obs-kind').value = s.value;
        replaceSel(obstacleKind(it, s.value));
        renderSel();
        if (s.value === 'building') toast(WALL_TIP);
      };
      kids.push(s);
      if (it.shape === 'wall') {
        kids.push(btn('✏️ 名稱', () => { const n = prompt('建築名稱（例如：教學樓）', it.name || ''); if (n !== null) { replaceSel({ ...it, name: n.trim() }); renderSel(); } }));
        kids.push(btn('🚪 開門', () => { doorBack = tool; setTool('door'); }));
        if (step === 3) kids.push(btn('🏢 畫裡面', () => { const id = it.id; go(7); enterBuilding(id, 0); }));
      }
    }
    if (t === 'path' || t === 'corridor') {
      const s = mk('select', { title: '路寬' });
      for (const w of WIDTHS) s.append(new Option(`路寬 ${w} m`, String(w), false, w === (it.width || 3)));
      s.onchange = () => { corrWidth = +s.value; replaceSel({ ...it, width: +s.value }); };
      kids.push(s);
    }
    if (t === 'block') {
      const s = kindSelect(it.kind);
      s.onchange = () => { $('block-kind').value = s.value; replaceSel({ ...it, kind: s.value }); };
      kids.push(s);
    }
    if (t === 'block' || t === 'anchor' || (t === 'part' && it.points.length > 2)) {
      kids.push(btn('✏️ 名稱', () => { const n = prompt('名稱', it.name || ''); if (n !== null && (n.trim() || t === 'part')) { replaceSel({ ...it, name: n.trim() }); renderSel(); } }));
    }
    if (t === 'part') kids.push(btn('🚪 開門', () => { doorBack = tool; setTool('idoor'); }));
    kids.push(btn('🧽 刪除', () => removeHit(sel)));
    kids.push(btn('✕', () => select(null), 'btn sm ghost sel-x'));
  }
  bar.replaceChildren(...kids);
  bar.classList.toggle('hidden', !kids.length);
}

/** Outline the picked thing. */
function drawSel(s) {
  const it = selItem();
  if (!it) return;
  ctx.save();
  ctx.strokeStyle = '#4f46e5';
  ctx.lineWidth = 3;
  ctx.setLineDash([7, 5]);
  ctx.beginPath();
  if (sel.type === 'anchor') ctx.arc(it.x * s, it.y * s, 17, 0, Math.PI * 2);
  else if (sel.type === 'block') ctx.rect(it.x * s - 3, it.y * s - 3, it.w * s + 6, it.h * s + 6);
  else if (sel.type === 'corridor') {
    const h = (it.width || 3) / 2;
    if (it.axis === 'h') ctx.rect(it.from * s, (it.c - h) * s, (it.to - it.from) * s, 2 * h * s);
    else ctx.rect((it.c - h) * s, it.from * s, 2 * h * s, (it.to - it.from) * s);
  } else {
    it.points.forEach((q, i) => (i ? ctx.lineTo(q.x * s, q.y * s) : ctx.moveTo(q.x * s, q.y * s)));
    if (sel.type !== 'path' && it.points.length > 2) ctx.closePath();
  }
  ctx.stroke();
  ctx.restore();
}

// ---------- step 7: building interiors (2-D drawing, 3-D view) ----------
/** Next / previous step in the wizard order; the interior step is skipped when there are no buildings. */
function stepAfter(n, dir) {
  let i = ORDER.indexOf(n) + dir;
  if (ORDER[i] === 7 && (!open() || !buildings(venue).length)) i += dir;
  return ORDER[Math.max(0, Math.min(ORDER.length - 1, i))];
}

/** Show only the tools of this step (and of this mode / walk / inside-or-not). */
function showTools() {
  document.querySelectorAll('#w-tools [data-steps], #more-menu [data-steps]').forEach((b) => {
    const ok = b.dataset.steps.split(' ').includes(String(step)) && (!b.dataset.mode || b.dataset.mode === wiz.mode)
      && (!b.dataset.walk || b.dataset.walk === (venue.walk || 'roads'))
      && (!b.dataset.in || step !== 7 || b.dataset.in === (inside ? '1' : '0'));
    b.classList.toggle('hidden', !ok);
  });
}

const curBuilding = () => (inside && venue.obstacles.find((o) => o.id === inside.id)) || null;
const curParts = () => {
  const b = curBuilding();
  return b ? floorsOf(b)[inside.fi]?.parts || [] : [];
};

/** The venue as drawn: the building being drawn inside shows the floor being drawn. */
function shownVenue() {
  if (step !== 7 || !inside) return venue;
  return { ...venue, obstacles: venue.obstacles.map((o) => (o.id === inside.id ? { ...o, floors: [floorsOf(o)[inside.fi]] } : o)) };
}

/** While drawing inside a building, fade everything outside it. */
function dimOutside(s) {
  const b = curBuilding();
  if (!b) return;
  ctx.beginPath();
  ctx.rect(0, 0, venue.width * s, venue.height * s);
  b.points.forEach((q, i) => (i ? ctx.lineTo(q.x * s, q.y * s) : ctx.moveTo(q.x * s, q.y * s)));
  ctx.closePath();
  ctx.fillStyle = 'rgba(226,232,240,.72)';
  ctx.fill('evenodd');
}

function pickBuilding(p) {
  const hits = buildings(venue).filter((b) => pointInPolygon(p, b.points));
  if (!hits.length) return toast(buildings(venue).length ? '請點在建築裡面' : '還沒有建築：回上一步用「建築」類型標出來');
  const area = (b) => { const xs = b.points.map((q) => q.x), ys = b.points.map((q) => q.y); return (Math.max(...xs) - Math.min(...xs)) * (Math.max(...ys) - Math.min(...ys)); };
  enterBuilding(hits.sort((a, b) => area(a) - area(b))[0].id, 0);
}

function enterBuilding(id, fi = 0) {
  inside = { id, fi };
  sel = null;
  view3d = false;
  enterFull();
}

function leaveBuilding() {
  inside = null;
  sel = null;
  enterFull();
}

function fitBuilding() {
  const b = curBuilding();
  const W = stage.clientWidth, H = stage.clientHeight;
  if (!b || !W || !H) return fit();
  const xs = b.points.map((q) => q.x), ys = b.points.map((q) => q.y);
  const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
  const pad = 30;
  view.k = Math.min(MAX_K, Math.max(0.01, Math.min((W - 2 * pad) / (x1 - x0 || 1), (H - 2 * pad) / (y1 - y0 || 1))));
  view.ox = (W - (x1 - x0) * view.k) / 2 - x0 * view.k;
  view.oy = (H - (y1 - y0) * view.k) / 2 - y0 * view.k;
  draw();
}

/** Title, floor menu and 3-D button for the interior step. */
function updateInside() {
  const b = curBuilding();
  if (inside && !b) inside = null;
  showTools();
  $('label-3d').textContent = view3d ? '平面圖' : '立體圖';
  $('w-prev').textContent = inside ? '← 全部建築' : '← 上一步';
  if (inside) {
    const fl = floorsOf(b);
    $('w-title').textContent = `${b.name || '建築'}・${fl[inside.fi].label}`;
    $('floor-sel').replaceChildren(...fl.map((f, i) => new Option(f.label, String(i), false, i === inside.fi)), new Option('＋ 加一層', 'add'));
  } else $('w-title').textContent = STEP_TITLE[7];
  setHint();
}

function addRoom(r) {
  const b = curBuilding();
  const room = makeRoom(b, curParts(), r, '');
  if (!room) { toast('房間要畫在建築裡面，而且至少 1 × 1 公尺'); return draw(); }
  draw();
  const name = prompt('房間名稱（例如：101 教室、男廁；可以不填）', '');
  if (name === null) return draw();
  commit(setFloorParts(venue, inside.id, inside.fi, [...curParts(), { ...room, name: name.trim() }]));
  select({ type: 'part', i: curParts().length - 1 });
}

/** Door tool inside: open / close a door in a room or inner wall (on 1F also the outer wall). */
function innerDoorAt(p) {
  const tol = Math.max(HIT_CSS / k(), 0.6);
  const b = curBuilding();
  const parts = curParts();
  let best = null;
  parts.forEach((q, i) => {
    const n = nearestOnRing(q.points, p);
    if (n.dist <= tol && (!best || n.dist < best.d)) best = { i, d: n.dist };
  });
  const outer = nearestOnRing(b.points, p);
  if (inside.fi === 0 && outer.dist <= tol && (!best || outer.dist < best.d)) {
    const nb = toggleDoor(b, p);
    commit({ ...venue, obstacles: venue.obstacles.map((o) => (o.id === b.id ? nb : o)) });
    return toast(nb.doors.length < (b.doors || []).length ? '已移除建築的出入口' : '已在外牆開一個出入口');
  }
  if (!best) return toast('請點在房間的牆或隔間牆上');
  const q = parts[best.i];
  const nq = toggleDoor(q, p, ROOM_DOOR_W);
  commit(setFloorParts(venue, inside.id, inside.fi, parts.map((x, i) => (i === best.i ? nq : x))));
  toast(nq.doors.length < (q.doors || []).length ? '已移除這個門' : '已開一個門；點綠點可以移除');
}

$('btn-3d').addEventListener('click', () => {
  view3d = !view3d;
  updateInside();
  updateBgButton();
  fit();
  if (view3d) toast('立體圖：一指拖曳移動、兩指縮放；點一棟建築畫它裡面');
});
$('btn-more').addEventListener('click', () => $('more-menu').classList.toggle('hidden'));
$('more-menu').addEventListener('click', (e) => { if (e.target.closest('button')) $('more-menu').classList.add('hidden'); });
$('floor-sel').addEventListener('change', () => {
  const v = $('floor-sel').value;
  if (v === 'add') {
    const nb = addFloor(curBuilding());
    commit({ ...venue, obstacles: venue.obstacles.map((o) => (o.id === nb.id ? nb : o)) });
    inside.fi = nb.floors.length - 1;
    toast(`已加上 ${nb.floors[inside.fi].label}`);
  } else inside.fi = +v;
  sel = null;
  renderSel();
  updateInside();
  draw();
});

// "走一圈": walk the building with the phone, starting at one of its doors
$('btn-walk').addEventListener('click', () => {
  const b = curBuilding();
  const doors = b.doors || [];
  if (!doors.length) return toast('這棟建築還沒有出入口：回上一步點這棟建築，按「開門」');
  if (doors.length === 1) return startSurvey(b, doors[0]);
  setTool('walkdoor');
  toast('點你要從哪個門走進去');
});
function walkFrom(p) {
  const b = curBuilding();
  const d = (b.doors || []).map((x) => ({ x, dist: Math.hypot(x.x - p.x, x.y - p.y) })).sort((a, c) => a.dist - c.dist)[0];
  if (!d || d.dist > Math.max(2, HIT_CSS / k())) return toast('請點在門（綠點）上');
  startSurvey(b, d.x);
}
function startSurvey(b, door) {
  const fl = floorsOf(b)[inside.fi];
  if (!confirm(`拿著手機從這個門走進「${b.name || '建築'}」，沿著牆走一圈。\n走完會自動放回這棟建築的 ${fl.label}（之後還可以在這裡修改）。\n\n要開始嗎？`)) return setTool('room');
  try {
    localStorage.setItem(SURVEY_TARGET, JSON.stringify({ id: b.id, name: b.name || '建築', floor: fl.label, door: { x: door.x, y: door.y }, inward: inwardAt(b, door) }));
  } catch { return toast('無法開始（瀏覽器儲存空間已滿）'); }
  location.href = 'survey.html';
}

/** Coming back from the survey: put the walked floors into the building (undoable). */
function applySurveyResult() {
  let r = null;
  try { r = JSON.parse(localStorage.getItem(SURVEY_RESULT)); } catch { /* none */ }
  localStorage.removeItem(SURVEY_RESULT);
  const b = r && venue.obstacles.find((o) => o.id === r.id);
  if (!b || !r.floors?.length) return false;
  let fl = floorsOf(b);
  for (const f of r.floors) {
    const i = fl.findIndex((x) => x.label === f.label);
    fl = i >= 0 ? fl.map((x, j) => (j === i ? { ...x, parts: f.parts } : x)) : [...fl, f];
  }
  commit({ ...venue, obstacles: venue.obstacles.map((o) => (o.id === b.id ? { ...o, floors: fl } : o)) });
  wiz.mode ||= venue.geo ? 'osm' : 'size';
  inside = { id: b.id, fi: Math.max(0, fl.findIndex((x) => x.label === r.floors[0].label)) };
  go(7);
  toast(`已放回「${b.name || '建築'}」：${r.floors.map((f) => f.label).join('、')}。位置不對可以按復原`);
  return true;
}

// ---------- automatic suggestions for each step (OSM data or the photo), reviewed by the user ----------
let osmCache = null; // { key, data } (OSM data in venue metres)
let photoRec = null; // { img, id, promise, result, scale, error, status }
let review = null; // { step, src, list, loading, focus } while the review sheet is open
const STATUS_ZH = { 'loading tesseract core': '載入辨識引擎', 'initializing tesseract': '初始化', 'loading language traineddata': '下載中英文字資料', 'initializing api': '初始化', 'recognizing text': '辨識文字' };
const STEP_WHAT = { 3: () => (open() ? '不能走的地方' : '路'), 4: () => '攤位與設施', 5: () => '定位點' };

/** Where suggestions come from right now: 'osm', 'photo' or null. */
function autoSource() {
  if (venue.geo) return 'osm';
  if (bg && !bg.osm && photoRec?.img === bg.img) return 'photo';
  return null;
}
function srcKey() {
  const src = autoSource();
  return src === 'osm' ? `osm:${venue.geo.osm}:${venue.walk}` : src === 'photo' ? `photo:${photoRec.id}:${venue.walk}` : '';
}

/** Read the photo (text, roads, buildings) in the background as soon as it is chosen. */
function startPhotoRecognition(img) {
  const rec = { img, id: Date.now(), result: null, error: null, scale: 1, status: '準備中' };
  photoRec = rec;
  rec.promise = (async () => {
    try {
      const { loadToCanvas, recognize } = await import('./recognize.js');
      if (!window.Tesseract) throw new Error('辨識引擎沒有載入（需要網路）');
      const canvas = await loadToCanvas(img);
      rec.scale = canvas.sourceScale || 1;
      rec.result = await recognize(canvas, (m) => {
        if (!m?.status) return;
        rec.status = `${STATUS_ZH[m.status] || m.status}${m.progress != null ? ` ${Math.round(m.progress * 100)}%` : ''}`;
        if (review?.loading && review.src === 'photo' && photoRec === rec) $('auto-status').textContent = `正在辨識照片（${rec.status}）…可以先用下方工具標示`;
      });
    } catch (err) {
      rec.error = err;
    }
    if (photoRec === rec) maybeOfferReview();
  })();
}

/** Open the review the first time a step is reached with a source (once per source and step). */
function maybeOfferReview() {
  if (step < 3 || step > 5 || $('full').classList.contains('hidden')) return;
  $('btn-auto').classList.toggle('hidden', !autoSource());
  const key = srcKey();
  if (key && !review && wiz.reviewed?.[step] !== key) openReview();
}

async function candidatesFor(src) {
  if (src === 'osm') {
    const geo = venue.geo;
    const key = JSON.stringify([geo.bbox, venue.width, venue.height]);
    if (osmCache?.key !== key) {
      let data, via = 'osm';
      try {
        data = projectOsm(await fetchOsmData(geo.bbox), geo.bbox, venue.width, venue.height);
      } catch {
        // the OSM servers are often busy or blocked: read the map image itself instead
        via = 'map';
        const say = (p) => { if (review?.loading && review.src === 'osm') $('auto-status').textContent = `OSM 伺服器連不上，改從地圖圖片辨識：${p}…`; };
        say('載入地圖');
        const area = await renderArea(geo.bbox, 3072);
        const { readTileMap } = await import('./tilemap.js');
        data = await readTileMap(area.canvas, venue.width / area.canvas.width, say);
      }
      osmCache = { key, data, via };
    }
    return osmCandidates(osmCache.data, venue);
  }
  const rec = photoRec;
  await rec.promise;
  if (rec.error) throw rec.error;
  const k = rec.scale * bg.mpp; // metres per recognition-canvas pixel
  return photoCandidates(rec.result, (x, y) => ({ x: bg.x + x * k, y: bg.y + y * k }), k, venue);
}

async function openReview() {
  const src = autoSource();
  if (step < 3 || step > 5) return;
  if (!src) return toast('自動辨識需要 OSM 地圖或導覽圖照片當底圖');
  const st = step;
  wiz.reviewed = { ...(wiz.reviewed || {}), [st]: srcKey() };
  saveWiz();
  const me = { step: st, src, list: [], loading: true, focus: null };
  review = me;
  $('auto-title').textContent = `自動辨識：${STEP_WHAT[st]()}`;
  $('auto-attr').textContent = src === 'osm'
    ? '資料 © OpenStreetMap contributors。保留之後可以用「移動」「刪除」修改。'
    : '名稱是從照片辨識的文字，可能有錯字，可以直接點名稱修改。';
  $('auto-sheet').classList.remove('hidden');
  $('auto-apply').classList.add('hidden');
  $('auto-close').textContent = '全部不要';
  $('auto-list').replaceChildren();
  $('auto-status').textContent = src === 'osm' ? '正在向 OpenStreetMap 查詢這個範圍…' : `正在辨識照片（${photoRec.status}）…可以先用下方工具標示`;
  let list;
  try {
    list = await candidatesFor(src);
  } catch (err) {
    if (review === me) {
      $('auto-status').textContent = `辨識失敗：${err.message}。可以先用下方工具自己標，或稍後按「自動辨識」再試。`;
      $('auto-close').textContent = '關閉';
      wiz.reviewed = { ...wiz.reviewed, [st]: null }; // try again next time
      saveWiz();
    }
    return;
  }
  if (review !== me || step !== st) return;
  if (src === 'osm' && osmCache?.via === 'map') $('auto-attr').textContent = '從 OSM 地圖圖片辨識（© OpenStreetMap contributors）。名稱是辨識出來的文字，可能有錯字，可以直接點名稱修改；門的位置是猜的。';
  me.list = list.filter((c) => c.step === st).map((c) => ({ ...c }));
  me.loading = false;
  showReview();
}

const candLabel = (c) => ({
  obstacle: () => (c.item.shape === 'wall' ? '建築（只擋牆）' : OBSTACLE_KINDS[c.item.kind]?.label || '不能走'),
  block: () => KINDS[c.item.kind]?.label || '攤位',
  anchor: () => c.item.landmark || '定位點',
  anchors: () => '定位點',
  corridor: () => '直路',
  path: () => '路',
}[c.type]());
const candColor = (c) => (c.type === 'obstacle' ? OBSTACLE_KINDS[c.item.kind]?.color : c.type === 'block' ? KINDS[c.item.kind]?.color : c.type === 'anchor' || c.type === 'anchors' ? '#e11d48' : '#4f46e5') || '#94a3b8';

function showReview() {
  const { list, step: st } = review;
  if (!list.length) {
    $('auto-status').textContent = `沒有辨識到${STEP_WHAT[st]()}，請用下方工具自己標。`;
    $('auto-close').textContent = '關閉';
    return draw();
  }
  $('auto-status').textContent = `找到 ${list.length} 項，已畫在地圖上。取消不要的、名稱可以直接改，再按「保留勾選的」。`;
  $('auto-list').replaceChildren(...list.map((c) => {
    const li = document.createElement('li');
    const label = document.createElement('label');
    const cb = Object.assign(document.createElement('input'), { type: 'checkbox', checked: c.on });
    cb.addEventListener('change', () => { c.on = cb.checked; label.classList.toggle('off', !c.on); focusOn(c); });
    const sw = document.createElement('span');
    sw.className = 'sw';
    sw.style.background = candColor(c);
    const nm = Object.assign(document.createElement('input'), { type: 'text', className: 'nm', value: c.name || '', placeholder: candLabel(c) });
    nm.addEventListener('change', () => { c.name = nm.value.trim(); draw(); });
    nm.addEventListener('focus', () => focusOn(c));
    const sm = document.createElement('small');
    sm.textContent = c.doubt ? '可能有錯字' : c.note || candLabel(c);
    if (c.doubt || c.note) sm.className = 'doubt';
    label.classList.toggle('off', !c.on);
    label.append(cb, sw, nm, sm);
    li.append(label);
    return li;
  }));
  $('auto-apply').classList.remove('hidden');
  draw();
}

function candPoints(c) {
  const it = c.item;
  if (c.type === 'obstacle' || c.type === 'path' || c.type === 'anchors') return it.points;
  if (c.type === 'block') return [{ x: it.x, y: it.y }, { x: it.x + it.w, y: it.y + it.h }];
  if (c.type === 'corridor') return it.axis === 'h' ? [{ x: it.from, y: it.c }, { x: it.to, y: it.c }] : [{ x: it.c, y: it.from }, { x: it.c, y: it.to }];
  return [{ x: it.x, y: it.y }];
}

/** Bring a suggestion into view above the sheet and highlight it. */
function focusOn(c) {
  review.focus = c.key;
  const P = candPoints(c);
  const xs = P.map((q) => q.x), ys = P.map((q) => q.y);
  const cx = (Math.min(...xs) + Math.max(...xs)) / 2, cy = (Math.min(...ys) + Math.max(...ys)) / 2;
  const W = stage.clientWidth || 300, H = stage.clientHeight || 300;
  const span = Math.max(Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys), 4);
  view.k = Math.min(view.k, (Math.min(W, H * 0.5) * 0.8) / span);
  view.k = Math.max(view.k, minK());
  view.ox = W / 2 - cx * view.k;
  view.oy = H * 0.26 - cy * view.k;
  draw();
}

/** Suggestions drawn over the map: kept ones strong, dropped ones faint, the focused one outlined. */
function drawReview(s) {
  for (const c of review.list) {
    const it = c.item;
    const focus = review.focus === c.key;
    ctx.globalAlpha = c.on ? 0.9 : 0.25;
    if (c.type === 'obstacle') drawObstacle(ctx, { ...it, name: c.name }, s, true);
    else if (c.type === 'block') {
      ctx.fillStyle = KINDS[it.kind]?.color || '#e2e8f0';
      ctx.fillRect(it.x * s, it.y * s, it.w * s, it.h * s);
    } else if (c.type === 'corridor' || c.type === 'path') {
      ctx.strokeStyle = 'rgba(79,70,229,.55)';
      ctx.lineWidth = Math.max(4, (it.width || 3) * s);
      ctx.lineCap = 'round';
      ctx.beginPath();
      candPoints(c).forEach((q, i) => (i ? ctx.lineTo(q.x * s, q.y * s) : ctx.moveTo(q.x * s, q.y * s)));
      ctx.stroke();
    }
    // dashed outline marks "suggested, not kept yet"
    ctx.setLineDash([6, 4]);
    ctx.strokeStyle = focus ? '#f59e0b' : '#7c3aed';
    ctx.lineWidth = focus ? 4 : 2;
    const P = candPoints(c);
    if (c.type === 'anchors') {
      ctx.setLineDash([]);
      ctx.fillStyle = '#e11d48';
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1.5;
      for (const q of P) {
        ctx.beginPath();
        ctx.arc(q.x * s, q.y * s, 5, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
      }
    } else if (c.type === 'anchor') {
      ctx.beginPath();
      ctx.arc(it.x * s, it.y * s, 10, 0, Math.PI * 2);
      ctx.fillStyle = '#e11d48';
      ctx.fill();
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = '#111827';
      ctx.font = '600 13px sans-serif';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      ctx.fillText(c.name || candLabel(c), it.x * s + 14, it.y * s);
    } else if (c.type === 'block') {
      ctx.strokeRect(it.x * s, it.y * s, it.w * s, it.h * s);
      ctx.setLineDash([]);
      ctx.fillStyle = '#111827';
      ctx.font = '600 12px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(c.name || '', (it.x + it.w / 2) * s, (it.y + it.h / 2) * s);
    } else if (c.type === 'obstacle') {
      ctx.beginPath();
      P.forEach((q, i) => (i ? ctx.lineTo(q.x * s, q.y * s) : ctx.moveTo(q.x * s, q.y * s)));
      ctx.closePath();
      ctx.stroke();
    } else if (focus) {
      ctx.beginPath();
      P.forEach((q, i) => (i ? ctx.lineTo(q.x * s, q.y * s) : ctx.moveTo(q.x * s, q.y * s)));
      ctx.stroke();
    }
    ctx.setLineDash([]);
  }
  ctx.globalAlpha = 1;
}

function closeReview() {
  review = null;
  $('auto-sheet').classList.add('hidden');
  draw();
}

$('btn-auto').addEventListener('click', () => { closeReview(); openReview(); });
$('auto-close').addEventListener('click', closeReview);
$('auto-apply').addEventListener('click', () => {
  if (!review || review.loading) return;
  const { step: st, src } = review;
  // an unnamed area stays unnamed (its kind label is not a name, and anchors are named after real names)
  const named = (c) => (c.type === 'corridor' || c.type === 'path' ? c : { ...c, item: { ...c.item, name: c.name || c.item.name || (c.type === 'obstacle' ? '' : candLabel(c)) } });
  const chosen = review.list.filter((c) => c.on).map(named);
  const next = applyCandidates(venue, st, chosen, src);
  const wanted = chosen.reduce((n, c) => n + (c.type === 'anchors' ? c.item.points.length : 1), 0);
  const dropped = st === 5 ? wanted - next.anchors.filter((a) => a.src).length : 0;
  closeReview();
  commit(next);
  if (!chosen.length) return toast('沒有保留任何項目');
  toast(`已保留 ${wanted - dropped} 項，可以用「移動」「刪除」修改${dropped ? `（${dropped} 個定位點在不能走的地方，沒有加入）` : ''}`);
});

let wandCache = null; // { img, data: ImageData, scale }
function bgPixels() {
  if (wandCache?.img === bg.img) return wandCache;
  const W = bg.img.width, H = bg.img.height;
  const scale = Math.min(1, 1200 / Math.max(W, H));
  const c = document.createElement('canvas');
  c.width = Math.max(1, Math.round(W * scale));
  c.height = Math.max(1, Math.round(H * scale));
  const g = c.getContext('2d', { willReadFrequently: true });
  g.drawImage(bg.img, 0, 0, c.width, c.height);
  wandCache = { img: bg.img, data: g.getImageData(0, 0, c.width, c.height), scale };
  return wandCache;
}

function wandAt(p) {
  if (!bg) return toast('需要底圖（OSM 地圖或照片）才能用魔術棒');
  let px;
  try { px = bgPixels(); } catch { return toast('這張底圖無法讀取顏色，請改用矩形或手繪'); }
  const { data, scale } = px;
  const ix = ((p.x - bg.x) / bg.mpp) * scale, iy = ((p.y - bg.y) / bg.mpp) * scale;
  if (ix < 0 || iy < 0 || ix >= data.width || iy >= data.height) return toast('請點在底圖上');
  const total = data.width * data.height;
  const r = floodRegion(data, ix, iy, 40, total * 0.4);
  if (r.overflow) return toast('這個顏色延伸太大（可能點到底色），請點在要標的區域裡面');
  if (r.count < 25) return toast('這塊太小了，請點在色塊比較大的地方');
  const mask = closing(r.mask, data.width, data.height, 1);
  const outline = traceOutline(mask, data.width, data.height);
  const pts = outline.map((q) => ({ x: bg.x + (q.x / scale) * bg.mpp, y: bg.y + (q.y / scale) * bg.mpp }));
  const o = newObstacle(pts, $('obs-kind').value);
  if (!o) return toast('範圍太小，請改用矩形或手繪');
  commit({ ...venue, obstacles: [...venue.obstacles, o] });
  toast(o.shape === 'wall' ? WALL_TIP : `已標上「${OBSTACLE_KINDS[o.kind].label}」，不對可以按復原`);
}

/** Why the user can't leave the current step yet ('' = ok). May apply the step's input. */
async function blocker() {
  if (step === 2) {
    if (wiz.mode === 'osm') {
      if (osm) return applyOsm();
      return venue.geo ? '' : '請先搜尋地點，並在地圖上框出活動範圍';
    }
    if (wiz.mode === 'photo') {
      if (!bg) return isEmpty(venue) ? '請先按下方「選照片」' : '';
      return photoScaled ? '' : '請在照片上點兩個位置，輸入實際距離來設定比例';
    }
    const w = +$('v-width').value, h = +$('v-height').value;
    if (!(w >= 5 && h >= 5 && w <= 1000 && h <= 1000)) return '寬和長請輸入 5–1000 公尺';
    if (w !== venue.width || h !== venue.height) {
      const { geo, ...rest } = venue;
      if (bg?.osm || geo) bg = null; // the OSM map no longer matches the size
      commit({ ...rest, width: w, height: h });
    }
    return '';
  }
  const fail = checkVenue(venue).find((c) => c.step === step && !c.ok);
  return fail ? fail.label : '';
}

$('w-next').addEventListener('click', async () => {
  const why = await blocker();
  if (why) return toast(why);
  go(stepAfter(step, 1));
});
$('w-prev').addEventListener('click', () => {
  if (step === 7 && inside) return leaveBuilding();
  go(stepAfter(step, -1));
});
$('btn-fit').addEventListener('click', fit);
document.querySelectorAll('#walk-seg button').forEach((b) => b.addEventListener('click', () => {
  if (venue.walk === b.dataset.walk) return;
  commit({ ...venue, walk: b.dataset.walk });
  enterFull();
  toast(b.dataset.walk === 'open' ? '自由走動：標出不能走的地方，其他都可以走' : '沿路走：只能沿著畫出來的路走');
}));
$('btn-undo').addEventListener('click', undo);
document.querySelectorAll('.tool').forEach((b) => b.addEventListener('click', () => setTool(b.dataset.tool)));

// step 1
document.querySelectorAll('button.src-card').forEach((b) => b.addEventListener('click', () => {
  wiz.mode = b.dataset.mode;
  go(2);
}));
$('btn-resume').addEventListener('click', () => go(lastStep >= 3 ? lastStep : 3));
// throw away everything (drawing, background photo/map, recognition results, undo) and go back to choosing a source
function startOver() {
  if (!confirm('捨棄目前所有的變更，從選圖開始？')) return;
  closeReview();
  bg = null;
  scalePts = [];
  photoScaled = false;
  osmCache = null;
  wiz.mode = null;
  wiz.reviewed = {};
  commit(newVenue('我的場地', 30, 20, 'open'));
  history = [];
  lastStep = 3;
  go(1);
  toast('已清空，請重新選擇場地來源');
}
$('btn-new').addEventListener('click', startOver);
document.querySelectorAll('.btn-restart').forEach((b) => b.addEventListener('click', startOver));
$('btn-sample').addEventListener('click', () => {
  bg = null;
  wiz.mode = 'size';
  commit(sampleVenue());
  go(3);
});
$('draft-file').addEventListener('change', async (e) => {
  const f = e.target.files[0];
  e.target.value = '';
  if (!f) return;
  try {
    const v = JSON.parse(await f.text());
    if (v.version !== 1 || !Array.isArray(v.corridors)) throw new Error('bad');
    bg = null;
    wiz.mode = v.geo ? 'osm' : 'size';
    commit(upgradeVenue(v));
    toast('已匯入草稿');
    go(3);
  } catch { toast('這不是編輯器的草稿檔'); }
});

// step 6
document.querySelectorAll('[data-go]').forEach((b) => b.addEventListener('click', () => {
  if (+b.dataset.go === 2 && !wiz.mode) wiz.mode = venue.geo ? 'osm' : 'size';
  go(+b.dataset.go);
}));
$('v-title').addEventListener('change', () => {
  venue = { ...venue, title: $('v-title').value.trim() || '我的場地' };
  save();
});
$('btn-save-draft').addEventListener('click', () => {
  download(new Blob([JSON.stringify(venue, null, 2)], { type: 'application/json' }), `${venue.title}.draft.json`);
});

// ---------- lists & checks (step 6), resume (step 1) ----------
function item({ num, name, onName, extra = [], onRemove }) {
  const li = document.createElement('li');
  li.className = 'place';
  const badge = document.createElement('span');
  badge.className = num ? 'pin' : 'dot';
  if (num) badge.textContent = num;
  const input = document.createElement('input');
  input.className = 'place-name';
  input.value = name;
  input.addEventListener('change', () => onName(input.value.trim() || name));
  const del = document.createElement('button');
  del.className = 'btn sm ghost';
  del.textContent = '✕';
  del.title = '刪除';
  del.onclick = onRemove;
  li.append(badge, input, ...extra, del);
  return li;
}

function landmarkInput(a) {
  const input = document.createElement('input');
  input.className = 'place-name landmark';
  input.placeholder = '現場看起來是什麼（選填）';
  input.value = a.landmark || '';
  input.addEventListener('change', () => commit({
    ...venue,
    anchors: venue.anchors.map((x) => {
      if (x.id !== a.id) return x;
      const { landmark, ...rest } = x;
      const v = input.value.trim();
      return v ? { ...rest, landmark: v } : rest;
    }),
  }));
  return input;
}

function kindSelect(value) {
  const s = document.createElement('select');
  for (const [key, v] of Object.entries(KINDS)) s.append(new Option(v.label, key, false, key === value));
  return s;
}

function refresh() {
  $('btn-undo').disabled = history.length === 0;
  if (step === 1) {
    const show = !isEmpty(venue) || !!venue.geo;
    $('resume').classList.toggle('hidden', !show);
    if (show) {
      const nWays = venue.corridors.length + (venue.paths || []).length;
      $('resume-info').textContent =
        `${venue.title}（${venue.width} × ${venue.height} m，${open() ? `自由走動、不能走的地方 ${venue.obstacles.length} 處` : `路 ${nWays} 條`}、攤位 ${venue.blocks.length} 個、定位點 ${venue.anchors.length} 個）`;
    }
  }
  if (step === 6) {
    drawStylePreview();
    $('v-title').value = venue.title;
    $('v-size').textContent = `場地 ${venue.width} × ${venue.height} m${venue.geo ? `（${venue.geo.name}）` : ''}`;
    $('anchor-items').replaceChildren(
      ...venue.anchors.map((a, i) =>
        item({
          num: i + 1,
          name: a.name,
          extra: [landmarkInput(a)],
          onName: (v) => commit({ ...venue, anchors: venue.anchors.map((x) => (x.id === a.id ? { ...x, name: v } : x)) }),
          onRemove: () => commit({ ...venue, anchors: venue.anchors.filter((x) => x.id !== a.id) }),
        })
      )
    );
    $('block-items').replaceChildren(
      ...venue.blocks.map((b) => {
        const sel = kindSelect(b.kind);
        sel.onchange = () => commit({ ...venue, blocks: venue.blocks.map((x) => (x.id === b.id ? { ...x, kind: sel.value } : x)) });
        return item({
          name: b.name,
          extra: [sel],
          onName: (v) => commit({ ...venue, blocks: venue.blocks.map((x) => (x.id === b.id ? { ...x, name: v } : x)) }),
          onRemove: () => commit({ ...venue, blocks: venue.blocks.filter((x) => x.id !== b.id) }),
        });
      })
    );
    $('anchor-count').textContent = venue.anchors.length;
    $('block-count').textContent = venue.blocks.length;
    $('anchor-empty').classList.toggle('hidden', venue.anchors.length > 0);
    $('block-empty').classList.toggle('hidden', venue.blocks.length > 0);
    const checks = checkVenue(venue);
    $('checks').innerHTML = checks.map((c) => `<li class="${c.ok ? 'ok' : 'bad'}">${c.label}</li>`).join('');
    const ok = checks.every((c) => c.ok);
    $('btn-download').disabled = !ok;
    $('btn-open').disabled = !ok;
  }
  draw();
}

// ---------- OpenStreetMap: find the venue, frame the event area (step 2) ----------
let osm = null; // { place, area: {canvas,toPx,toLatLon}, rect: {x0,y0,x1,y1} in area pixels }
const ocv = $('osm-map');

const fmtArea = (m2) => (m2 >= 10000
  ? `${(m2 / 10000).toFixed(2)} 公頃（${Math.round(m2).toLocaleString()} m²）`
  : `${Math.round(m2).toLocaleString()} m²`);

$('osm-search').addEventListener('click', doSearch);
$('osm-q').addEventListener('keydown', (e) => { if (e.key === 'Enter') doSearch(); });

const note = (text) => Object.assign(document.createElement('li'), { className: 'muted', textContent: text });

function osmEnter() {
  const cur = venue.geo;
  $('osm-current').classList.toggle('hidden', !cur || !!osm);
  if (cur) {
    if (!$('osm-q').value) $('osm-q').value = cur.name;
    $('osm-current').textContent = `目前的範圍：${cur.name}，${venue.width} × ${venue.height} m。要沿用就直接按「下一步」，或重新搜尋。`;
  }
  if (osm) requestAnimationFrame(drawPicker);
}

async function doSearch() {
  const q = $('osm-q').value.trim();
  if (!q) return toast('請輸入地點名稱');
  $('osm-q').blur();
  const list = $('osm-results');
  osm = null;
  $('osm-pick').classList.add('hidden');
  $('osm-current').classList.add('hidden');
  list.classList.remove('hidden');
  list.replaceChildren(note('搜尋中…'));
  try {
    const res = await searchPlaces(q);
    if (!res.length) return list.replaceChildren(note('找不到這個地點，換個名稱試試（例如加上城市）。'));
    list.replaceChildren(...res.map((r) => {
      const li = document.createElement('li');
      const b = document.createElement('button');
      b.className = 'btn sm';
      const { width, height } = bboxSize(r.bbox);
      const name = document.createElement('span');
      name.textContent = r.name;
      const sub = document.createElement('small');
      sub.textContent = `${r.display}｜${r.area ? fmtArea(r.area) : `約 ${Math.round(width)} × ${Math.round(height)} m`}`;
      b.append(name, sub);
      b.onclick = () => openPicker(r);
      li.append(b);
      return li;
    }));
  } catch (err) {
    list.replaceChildren(note(`搜尋失敗：${err.message}（需要網路）`));
  }
}

async function openPicker(place) {
  $('osm-results').classList.add('hidden');
  $('osm-pick').classList.remove('hidden');
  $('osm-info').textContent = '載入 OSM 地圖中…';
  const b = place.bbox;
  const { width } = bboxSize(b);
  // show some surroundings (25 % each side, at least ~60 m)
  const padLat = Math.max((b.n - b.s) * 0.25, 60 / 111195);
  const padLon = Math.max((b.e - b.w) * 0.25, ((b.e - b.w) / Math.max(width, 1)) * 60);
  const view = { s: b.s - padLat, n: b.n + padLat, w: b.w - padLon, e: b.e + padLon };
  const area = await renderArea(view, 1024);
  osm = { place, area, rect: null };
  fullRect();
  ocv.width = area.canvas.width;
  ocv.height = area.canvas.height;
  drawPicker();
}

/** Fit the picker canvas inside the space left in the pane. */
function sizePicker() {
  const box = $('osm-canvas-wrap');
  const W = box.clientWidth, H = box.clientHeight;
  if (!W || !H || !ocv.width) return;
  const f = Math.min(W / ocv.width, H / ocv.height);
  ocv.style.width = `${Math.floor(ocv.width * f)}px`;
  ocv.style.height = `${Math.floor(ocv.height * f)}px`;
}

function fullRect() {
  const b = osm.place.bbox;
  const p0 = osm.area.toPx(b.n, b.w), p1 = osm.area.toPx(b.s, b.e);
  osm.rect = { x0: p0.x, y0: p0.y, x1: p1.x, y1: p1.y };
}

function rectBbox(r) {
  const a = osm.area.toLatLon(Math.min(r.x0, r.x1), Math.min(r.y0, r.y1));
  const c = osm.area.toLatLon(Math.max(r.x0, r.x1), Math.max(r.y0, r.y1));
  return { n: a.lat, w: a.lon, s: c.lat, e: c.lon };
}

function drawPicker() {
  if (!osm) return;
  sizePicker();
  const g = ocv.getContext('2d');
  const { canvas, toPx } = osm.area;
  g.drawImage(canvas, 0, 0);
  // place boundary from OSM
  const geo = osm.place.geojson;
  const polys = geo?.type === 'Polygon' ? [geo.coordinates] : geo?.type === 'MultiPolygon' ? geo.coordinates : [];
  g.strokeStyle = '#16a34a';
  g.lineWidth = 3;
  for (const rings of polys) {
    g.beginPath();
    rings[0].forEach(([lon, lat], i) => { const p = toPx(lat, lon); if (i) g.lineTo(p.x, p.y); else g.moveTo(p.x, p.y); });
    g.closePath();
    g.stroke();
  }
  // dim everything outside the event rectangle
  const r = osm.rect;
  const x = Math.min(r.x0, r.x1), y = Math.min(r.y0, r.y1), w = Math.abs(r.x1 - r.x0), h = Math.abs(r.y1 - r.y0);
  g.fillStyle = 'rgba(15,23,42,.35)';
  g.beginPath();
  g.rect(0, 0, ocv.width, ocv.height);
  g.rect(x, y, w, h);
  g.fill('evenodd');
  g.strokeStyle = '#4f46e5';
  g.lineWidth = 3;
  g.strokeRect(x, y, w, h);

  const sz = bboxSize(rectBbox(r));
  const p = osm.place;
  const full = bboxSize(p.bbox);
  $('osm-info').innerHTML = '';
  const b = document.createElement('b');
  b.textContent = `活動範圍 ${Math.round(sz.width)} × ${Math.round(sz.height)} m（${fmtArea(sz.width * sz.height)}）`;
  $('osm-info').append(b, document.createElement('br'),
    `${p.name}：${p.area ? `OSM 面積約 ${fmtArea(p.area)}，` : ''}外框約 ${Math.round(full.width)} × ${Math.round(full.height)} m`);
}

function opx(e) {
  const r = ocv.getBoundingClientRect();
  return { x: ((e.clientX - r.left) / r.width) * ocv.width, y: ((e.clientY - r.top) / r.height) * ocv.height };
}
let odrag = null;
ocv.addEventListener('pointerdown', (e) => {
  if (!osm) return;
  const p = opx(e);
  odrag = { prev: osm.rect };
  osm.rect = { x0: p.x, y0: p.y, x1: p.x, y1: p.y };
  try { ocv.setPointerCapture(e.pointerId); } catch { /* synthetic pointer */ }
});
ocv.addEventListener('pointermove', (e) => {
  if (!odrag) return;
  const p = opx(e);
  osm.rect.x1 = p.x;
  osm.rect.y1 = p.y;
  drawPicker();
});
ocv.addEventListener('pointerup', () => {
  if (!odrag) return;
  const r = osm.rect;
  if (Math.abs(r.x1 - r.x0) < 8 || Math.abs(r.y1 - r.y0) < 8) osm.rect = odrag.prev; // a tap, not a box
  odrag = null;
  drawPicker();
});
$('osm-full').addEventListener('click', () => {
  if (!osm) return toast('請先搜尋並選擇地點');
  fullRect();
  drawPicker();
});

/** Use the framed rectangle as the venue; returns why not ('' = applied). */
function applyOsm() {
  const bbox = rectBbox(osm.rect);
  const sz = bboxSize(bbox);
  const W = Math.round(sz.width), H = Math.round(sz.height);
  if (W > 1000 || H > 1000) return '範圍太大（上限 1000 × 1000 m），請框小一點';
  if (W < 5 || H < 5) return '範圍太小，請框大一點';
  const place = osm.place;
  const title = !venue.title || venue.title === '我的場地' ? place.name : venue.title;
  bg = null;
  commit({ ...venue, title, width: W, height: H, geo: { name: place.name, osm: place.osm, bbox } });
  osm = null;
  $('osm-pick').classList.add('hidden');
  toast(`場地已設為 ${W} × ${H} m，正在載入 OSM 底圖…`);
  return '';
}

// ---------- map style (exported image only) ----------
// venues framed on OSM default to the OSM map itself, so the result matches what the user saw
const mapStyle = () => {
  const st = venue.mapStyle || (venue.geo ? 'osm' : 'stone');
  return st === 'osm' && !venue.geo ? 'stone' : st;
};
/** OSM image of the venue's bbox at most maxPx wide (cached per bbox and size). */
const osmImages = new Map();
function osmImage(maxPx) {
  const key = JSON.stringify(venue.geo.bbox) + maxPx;
  if (!osmImages.has(key)) osmImages.set(key, renderArea(venue.geo.bbox, maxPx).then((a) => a.canvas));
  return osmImages.get(key);
}
/** The exported map image and the pixels per metre it is drawn at. */
async function mapImage(maxPx = MAX_PX) {
  if (mapStyle() === 'osm') {
    const base = await osmImage(maxPx);
    // keep the OSM image's own resolution (no blurry upscaling); coordinates follow this ppm
    // (small venues get at least 8 px/m so the image is not tiny; OSM tiles stop at zoom 19)
    const ppm = Math.min(Math.max(base.width / venue.width, 8), maxPx / Math.max(venue.width, venue.height));
    return { ppm, img: renderVenue(venue, ppm, 'osm', base) };
  }
  const ppm = maxPx === MAX_PX ? pxPerMeterFor(venue) : maxPx / Math.max(venue.width, venue.height);
  return { ppm, img: renderVenue(venue, ppm, mapStyle()) };
}
async function drawStylePreview() {
  document.querySelectorAll('#map-style button').forEach((b) => {
    b.classList.toggle('on', b.dataset.style === mapStyle());
    b.classList.toggle('hidden', b.dataset.style === 'osm' && !venue.geo);
  });
  const c = $('style-preview');
  const want = mapStyle();
  const { img } = await mapImage(Math.min(900, c.parentElement.clientWidth || 600));
  if (want !== mapStyle()) return; // changed while loading
  c.width = img.width;
  c.height = img.height;
  c.getContext('2d').drawImage(img, 0, 0);
}
document.querySelectorAll('#map-style button').forEach((b) => b.addEventListener('click', () => {
  if (b.dataset.style !== mapStyle()) commit({ ...venue, mapStyle: b.dataset.style });
}));

// ---------- export ----------
async function exportPhop() {
  const { ppm, img } = await mapImage();
  const p = buildPayload(venue, ppm);
  const blob = await new Promise((r) => img.toBlob(r, 'image/webp', 0.9));
  const ext = blob.type === 'image/webp' ? 'webp' : 'png';
  const payload = {
    [`map.${ext}`]: new Uint8Array(await blob.arrayBuffer()),
    'graph.json': JSON.stringify(p.graph),
    'anchors.json': JSON.stringify(p.anchors),
    'pois.json': JSON.stringify(p.pois),
    'calibration.json': JSON.stringify(p.calibration),
  };
  const manifest = {
    title: venue.title,
    map: `payload/map.${ext}`,
    source: 'editor',
    ...(p.walkMode === 'open' ? { walkMode: 'open' } : {}),
    coordinateSystem: {
      origin: 'top-left', xAxis: 'right', yAxis: 'down', unit: 'px',
      width: p.size.width, height: p.size.height,
      metersWidth: venue.width, metersHeight: venue.height,
      allowedDirections: ['up', 'down', 'left', 'right'],
    },
    floors: [{ id: 'F1', name: '1F', z: 0 }],
  };
  return buildPhop(manifest, payload, 'UNLICENSED');
}

function download(blob, name) {
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = name;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 5000);
}

$('btn-download').addEventListener('click', async () => {
  download(await exportPhop(), `${venue.title}.phop`);
  toast('已下載 .phop');
});
$('btn-open').addEventListener('click', async () => {
  await saveHandoff(await exportPhop());
  location.href = 'view.html?handoff=1';
});

// ---------- sample ----------
function sampleVenue() {
  let v = newVenue('範例市集', 40, 24);
  const c = (a, b) => { v = addCorridor(v, makeCorridor(v, a, b, 3)); };
  c({ x: 3, y: 12 }, { x: 37, y: 12 }); // main east–west aisle
  c({ x: 3, y: 3 }, { x: 3, y: 22 }); // west aisle
  c({ x: 20, y: 3 }, { x: 20, y: 22 }); // middle aisle
  c({ x: 37, y: 3 }, { x: 37, y: 12 }); // east aisle
  const B = (name, kind, x, y, w, h) => v.blocks.push({ id: nextId(v.blocks, 'B'), name, kind, x, y, w, h });
  ['A1', 'A2', 'A3'].forEach((n, i) => B(`攤位 ${n}`, 'booth', 5.5 + i * 4.5, 4, 4, 5.5));
  ['B1', 'B2', 'B3'].forEach((n, i) => B(`攤位 ${n}`, 'booth', 5.5 + i * 4.5, 14.5, 4, 5.5));
  B('舞台', 'stage', 22.5, 3, 12, 6.5);
  B('洗手間', 'restroom', 22.5, 14.5, 5, 5);
  B('服務台', 'info', 29.5, 14.5, 5, 5);
  B('入口', 'entrance', 0, 22.5, 6, 1.5);
  // a curved garden path from the middle aisle round to the east aisle
  v = addPath(v, makePath(v, [{ x: 20, y: 21 }, { x: 24, y: 22 }, { x: 28, y: 22.5 }, { x: 32, y: 22 }, { x: 35, y: 20.5 }, { x: 36.5, y: 17.5 }, { x: 37, y: 12 }]));
  const at = (p) => { const s = snapToCorridor(v, p); return { x: s.x, y: s.y }; };
  v.anchors.push({ id: 'A1', name: '入口', ...at({ x: 3, y: 22 }) });
  v.anchors.push({ id: 'A2', name: '服務台', ...at({ x: 32, y: 12 }) });
  v.anchors.push({ id: 'A3', name: '花園小徑', ...at({ x: 30, y: 23 }) });
  return v;
}

// ---------- start ----------
for (const [key, v] of Object.entries(OBSTACLE_KINDS)) $('obs-kind').append(new Option(v.label, key));
$('block-kind').replaceWith(Object.assign(kindSelect('booth'), { id: 'block-kind', hidden: true }));
new ResizeObserver(() => { layout(); drawPicker(); }).observe(stage);
// resume where the user left off (step 2 needs its in-memory state, so it restarts at step 1)
if (!applySurveyResult()) go(wiz.step >= 3 && !isEmpty(venue) ? wiz.step : 1);

// a walking survey can hand over an evacuation map photo, already turned and scaled to the drawing
async function restoreSurveyBackground() {
  const token = venue.surveyBg;
  try {
    const rec = await getBlob('editor-bg');
    if (!rec || rec.token !== token || venue.surveyBg !== token || bg) return;
    const img = await createImageBitmap(rec.blob);
    setBackground(img, false);
    Object.assign(bg, { x: rec.x, y: rec.y, mpp: rec.mpp, opacity: 0.6 });
    updateBgButton();
    draw();
  } catch { /* no IndexedDB: draw without it */ }
}
if (venue.surveyBg) restoreSurveyBackground();
